use vstd::prelude::*;

verus! {
    // Extract `count` bytes from `buffer` starting at `offset`.
    // We require `offset + count <= buffer.len()` so the slice is in‐bounds.
    fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> (slice: Vec<u8>)
        requires
            offset + count <= buffer.len(),
        ensures
            // The resulting vector has exactly `count` elements...
            slice.len() == count,
            // ...and for each index i < count, slice[i] == buffer[offset + i].
            forall |i: usize| i < count ==> slice[i] == buffer[offset + i],
    {
        buffer[offset..offset + count].to_vec()
    }
}

